% System setup
m1=3; m2=5; c1=2; c2=5; k1=4; k2=12;
A=[0 1 0 0;
   -(k1+k2)/m1 -(c1+c2)/m1  k2/m1  c2/m1;
   0 0 0 1;
   k2/m2 c2/m2 -k2/m2 -c2/m2];
B=[0;1/m1;0;0];

% Reference signal definition
w = 2*pi*1;
Aref = 0.8;
r  = @(t) Aref*sin(w*t);
rd = @(t) Aref*w*cos(w*t);
rdd = @(t) -Aref*w^2*sin(w*t);

% PID tuning
Kp = 120;
Ki = 10;
Kd = 35;

% Combined plant + controller dynamics
f = @(t,X) [A*X(1:4) + B*( ...
        Kp*(r(t)-X(1)) + Ki*X(5) + Kd*(rd(t)-X(2)) ...
        + m1*rdd(t) + c1*rd(t) + k1*r(t) ...
        + c2*(rd(t)-X(4)) + k2*(r(t)-X(3)) ...
    );
    r(t) - X(1)];

% Integration
tspan = [0 8];
X0 = [0 0 0 0 0]';
[t,X] = ode45(f,tspan,X0);

x1  = X(:,1);
ref = Aref*sin(w*t);

% Output comparison
figure; %[output:711ba810]
plot(t,ref,'--',t,x1,'-','LineWidth',1.5); %[output:711ba810]
grid on; %[output:711ba810]
xlabel('Time (s)'); ylabel('x_1 (m)'); %[output:711ba810]
legend('ref','x_1'); %[output:711ba810]
title('Tracking with PID and Feedforward'); %[output:711ba810]

